const CACHE='saras-next-timed-lips-v10';const FILES=['/runtime-assets/speech-rig.js','/runtime-assets/hamster-visemes.png','/runtime-assets/hamster-atlas.png','/runtime-assets/assistant-router.js','/runtime-assets/assistant.js','/runtime-assets/assistant.css','/runtime-assets/network.js','/','/runtime-assets/style.css','/runtime-assets/app.js','/runtime-assets/wake.js','/runtime-assets/voice.js','/runtime-assets/stream.js','/runtime-assets/voice-settings.js','/runtime-assets/workflows.js','/runtime-assets/ai-settings.js','/runtime-assets/icon.svg','/manifest.json','/runtime-assets/icon-192.png','/runtime-assets/icon-512.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES.map(url=>new Request(url,{cache:'reload'}))))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||(/^(?:\/account\/[0-9a-f]{32})?\/api(?:\/|$)/.test(new URL(e.request.url).pathname)))return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request,{ignoreSearch:true})))});self.addEventListener('notificationclick',e=>{e.notification.close();e.waitUntil(clients.openWindow('/'))});


self.addEventListener('push',e=>{let data={};try{data=e.data.json()}catch{}e.waitUntil(self.registration.showNotification(data.title||'SARAS',{body:data.body||'You have a reminder',tag:data.tag,icon:'/runtime-assets/icon-192.png'}))});
